#include "wiegand_rfid.h"

#include <stdio.h>
#include <string.h>

/* Bit index 0 is the most significant bit of byte 0, matching the firmware's
 * bit_lib convention. */
static void set_bit(uint8_t* buf, int index, bool value) {
    if(value) {
        buf[index / 8] |= (uint8_t)(1u << (7 - (index % 8)));
    } else {
        buf[index / 8] &= (uint8_t)~(1u << (7 - (index % 8)));
    }
}

static uint32_t field(const volatile bool* bits, int start, int len) {
    uint32_t v = 0;
    for(int i = 0; i < len; i++) {
        v = (v << 1) | (bits[start + i] ? 1u : 0u);
    }
    return v;
}

const char* wiegand_rfid_keytype(int n) {
    if(n == 26) return "H10301";
    if(n >= 27 && n <= 43) return "HIDProx";
    return NULL;
}

/* HID 26-bit. LFRFID stores 3 bytes: facility code, card high, card low.
 * (protocol_h10301.c: data[0]=FC, data[1]=CN>>8, data[2]=CN&0xFF.) */
static void build_h10301(const volatile bool* bits, uint8_t* out, size_t* out_len) {
    uint32_t fc = field(bits, 1, 8);
    uint32_t cn = field(bits, 9, 16);
    out[0] = (uint8_t)fc;
    out[1] = (uint8_t)(cn >> 8);
    out[2] = (uint8_t)(cn & 0xFF);
    *out_len = 3;
}

/* Generic HIDProx. The decoded field is 44 bits in a 6-byte buffer. The frame
 * sits right-justified (its last bit at bit 43) and the bits above it encode
 * the length the way the firmware's length decoder expects:
 *   n == 37      : bits 0..6 are 0, data in bits 7..43.
 *   38 <= n <= 43: a single 1 at bit (43 - n), in bits 0..5, then the data.
 *   27 <= n <= 36: a 1 at bit 6, then a 1 at bit (43 - n) in bits 7..16, then
 *                  the data.
 * In every case the data starts at bit (44 - n). */
static void build_hidprox(const volatile bool* bits, int n, uint8_t* out, size_t* out_len) {
    memset(out, 0, 6);
    if(n == 37) {
        /* no marker bits */
    } else if(n >= 38 && n <= 43) {
        set_bit(out, 43 - n, true);
    } else { /* 27..36 */
        set_bit(out, 6, true);
        set_bit(out, 43 - n, true);
    }
    int data_start = 44 - n;
    for(int i = 0; i < n; i++) {
        set_bit(out, data_start + i, bits[i]);
    }
    *out_len = 6;
}

bool wiegand_rfid_build(
    const volatile bool* bits,
    int n,
    uint8_t* out,
    size_t* out_len,
    const char** keytype,
    char* reason,
    size_t reason_size) {
    const char* type = wiegand_rfid_keytype(n);
    if(type == NULL) {
        if(n < 26) {
            snprintf(reason, reason_size, "%d bits: too short for HID", n);
        } else {
            snprintf(reason, reason_size, "%d bits: no HID key type", n);
        }
        return false;
    }

    if(n == 26) {
        build_h10301(bits, out, out_len);
    } else {
        build_hidprox(bits, n, out, out_len);
    }
    *keytype = type;
    return true;
}
